var player=UnityEngine.GameObject.FindGameObjectWithTag("Player");var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Weapons/Enemy_Entity.prefab");var enemy=UnityEngine.Object.Instantiate(prefab,player.transform.position+UnityEngine.Vector3.forward*3f,UnityEngine.Quaternion.identity);var health=enemy.GetComponent<SoulHunter.Gameplay.Combat.HealthController>();var before=health.CurrentHealth;health.TakeDamage(new SoulHunter.Gameplay.Combat.DamagePacket(15,enemy.transform.position,UnityEngine.Vector3.zero));return new{before,after=health.CurrentHealth,active=enemy.activeSelf,damagePopup=SoulHunter.Gameplay.UI.DamagePopupManager.Instance!=null,vfx=SoulHunter.Gameplay.VFX.VFXPoolManager.Instance!=null};
